def to_snake_case(s: str) -> str:
    result = []
    for i, ch in enumerate(s):
        if ch.isupper():
            if i > 0 and (s[i-1].islower() or (i+1 < len(s) and s[i+1].islower())):
                result.append('_')
            result.append(ch.lower())
        else:
            result.append(ch)
    return ''.join(result)
